WITH valid_web_events AS (SELECT * FROM web_events WHERE page IS NULL), web_events_stats AS (SELECT page, event_type, COUNT(*) AS web_event_count, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM valid_web_events GROUP BY page, event_type) SELECT page, event_type, web_event_count, avg_duration_sec FROM web_events_stats WHERE web_event_count >= 4 ORDER BY web_event_count DESC, page ASC, event_type ASC LIMIT 5;
